import{_ as a,o as l,c as r,a2 as d}from"./chunks/framework.CqpfiAoK.js";const u=JSON.parse('{"title":"医療保障法","description":"","frontmatter":{},"headers":[],"relativePath":"ja/44-医疗保障法.md","filePath":"ja/44-医疗保障法.md","lastUpdated":1789183869000}'),i={name:"ja/44-医疗保障法.md"};function e(o,t,h,n,s,b){return l(),r("div",null,[...t[0]||(t[0]=[d('<h1 id="医療保障法" tabindex="-1">医療保障法 <a class="header-anchor" href="#医療保障法" aria-label="Permalink to &quot;医療保障法&quot;">​</a></h1><table tabindex="0"><thead><tr><th>プロジェクト</th><th>内容</th></tr></thead><tbody><tr><td>文書番号</td><td>44</td></tr><tr><td>所属モジュール</td><td>法律体系と統治枠組み</td></tr><tr><td>コアキーワード</td><td>医療権、共生医療、修練損傷治療、生命健康、医療保険体系</td></tr></tbody></table><h2 id="第一節-立法目的と基本原則" tabindex="-1">第一節 立法目的と基本原則 <a class="header-anchor" href="#第一節-立法目的と基本原則" aria-label="Permalink to &quot;第一節 立法目的と基本原則&quot;">​</a></h2><p>《医療保障法》はアンカー共生文明の五部の付帯法の一つであり、衡元宙内のすべての生命の健康権と医療権を保障し、万族をカバーする共生医療体系を構築し、各生命が病気や怪我の際にタイムリーで効果的な治療を受けられることを確保することを目的とする。</p><p>本法は以下の基本原則を確立する：</p><table tabindex="0"><thead><tr><th>原則</th><th>内包</th></tr></thead><tbody><tr><td>健康優先原則</td><td>生命健康はすべての進化の基礎であり、国家と文明は生命健康の保障を優先的な地位に置く</td></tr><tr><td>普遍カバー原則</td><td>医療保障はすべての生命をカバーし、種族、修為、出身、経済状況を問わない</td></tr><tr><td>階層診療原則</td><td>基層医療、区域医療、高階医療の三級診療体系を構築し、医療資源を合理的に配分する</td></tr><tr><td>防治結合原則</td><td>予防を主とし、予防と治療を結合し、修練損傷の予防とリハビリテーションを重視する</td></tr><tr><td>異族適応原則</td><td>異なる種族の生理的特性に応じて適応した医療方案を提供し、人族基準で一律に処理することを禁止する</td></tr><tr><td>公益属性原則</td><td>基本医療サービスは公益属性を有し、営利目的で生命の治療権を剥奪してはならない</td></tr></tbody></table><h2 id="第二節-生命健康権の法律保障" tabindex="-1">第二節 生命健康権の法律保障 <a class="header-anchor" href="#第二節-生命健康権の法律保障" aria-label="Permalink to &quot;第二節 生命健康権の法律保障&quot;">​</a></h2><p>本法は、生命健康権は共生憲法が各生命に付与した基本権利であり、具体的に以下を含むことを明確に規定する：</p><ol><li><strong>基本医療権</strong>: 各生命は無料の基本医療サービスを受ける権利を有し、一般疾患の診断治療、基本薬物、定期健康診断などを含む。</li><li><strong>救急救治権</strong>: 各生命は突発的な病気や怪我の際に緊急治療を受ける権利を有し、医療機関はいかなる理由でも救急治療を拒否してはならない。</li><li><strong>修練損傷救治権</strong>: 修練者が修練過程で受けたエネルギー紊乱、経絡損傷、走火入魔などの損傷について、専門的な治療を受ける権利を有する。</li><li><strong>知情同意権</strong>: 患者は自身の病状、治療方案、リスクと予後を知る権利を有し、治療方案を選択または拒否する権利を有する。</li><li><strong>プライバシー保護権</strong>: 患者の医療情報と身体データは法律で保護され、患者の同意なしに漏洩または他の目的に使用してはならない。</li><li><strong>リハビリ保障権</strong>: 病気や怪我の患者はリハビリ治療と補助器具を受ける権利を有し、労働と生活能力の回復を支援する。</li></ol><h2 id="第三節-共生医療体系架构" tabindex="-1">第三節 共生医療体系架构 <a class="header-anchor" href="#第三節-共生医療体系架构" aria-label="Permalink to &quot;第三節 共生医療体系架构&quot;">​</a></h2><p>アンカー共生文明の医療体系は三級に分かれ、各級の間に紹介と協力の仕組みが構築されている：</p><table tabindex="0"><thead><tr><th>級</th><th>名称</th><th>職能</th><th>カバー範囲</th></tr></thead><tbody><tr><td>第一級</td><td>基層医療ステーション</td><td>一般疾患の診断治療、予防保健、基本健康診断、救急搬送</td><td>コミュニティ/村落/小型位面</td></tr><tr><td>第二級</td><td>区域医療センター</td><td>専門診療、手術治療、修練損傷の初期処理、リハビリ</td><td>都市/区域/中型位面</td></tr><tr><td>第三級</td><td>高階医療総院</td><td>難治重症、高階修練損傷、意識域疾患、跨種族難病</td><td>文明核心/大型位面</td></tr></tbody></table><p>さらに、「修練損傷専門科」を設立する：修練過程における各種損傷を専門的に処理し、エネルギー過負荷、経絡断裂、心魔侵入、霊魂創傷などを含み、修練法則に精通した医療人員を配置する。</p><h2 id="第四節-医療保障基金" tabindex="-1">第四節 医療保障基金 <a class="header-anchor" href="#第四節-医療保障基金" aria-label="Permalink to &quot;第四節 医療保障基金&quot;">​</a></h2><p>医療保障基金は共生医療体系運営の経済基礎であり、その出所は以下を含む：</p><ul><li>公共積立金の交付（主な出所）</li><li>聯産承包机制における医療保障の積立</li><li>社会寄付</li><li>基金投資収益</li></ul><p>基金の支払範囲は以下を含む：基本医療サービス費用、救急費用、修練損傷治療費用、基本薬物費用、リハビリ費用など。患者個人はわずかな自己負担費用のみを支払い、経済困難者には減免を実施する。</p><h2 id="第五節-医療機関と医療人員" tabindex="-1">第五節 医療機関と医療人員 <a class="header-anchor" href="#第五節-医療機関と医療人員" aria-label="Permalink to &quot;第五節 医療機関と医療人員&quot;">​</a></h2><ul><li><strong>公立医療機関</strong>: 国家または文明共同体によって設立され、基本医療サービスと公衆衛生職能を担い、経費は医療保障基金によって保障される。</li><li><strong>私立医療機関</strong>: 社会力量によって法律に基づいて設立され、高端医療サービスを提供できるが、医療主管部門の監督を受けなければならず、救急患者を拒否してはならない。</li><li><strong>異族医療機関</strong>: 特殊種族の生理的ニーズに対応して設立された専門医療機関で、異族医療人員を配置する。</li><li><strong>医療人員の権利と義務</strong>: 医療人員は執業保護、合理的報酬、職業訓練などの権利を享有すると同時に、救命救急、患者尊重、医療秘密保持などの義務を負う。</li></ul><h2 id="第六節-公衆衛生と予防" tabindex="-1">第六節 公衆衛生と予防 <a class="header-anchor" href="#第六節-公衆衛生と予防" aria-label="Permalink to &quot;第六節 公衆衛生と予防&quot;">​</a></h2><p>国家は公衆衛生体系を構築し、以下の職能を履行する：</p><ol><li>伝染病の監視と予防制御、跨位面疫情警報机制を構築する。</li><li>全民健康診断と健康記録管理。</li><li>修練安全宣伝と修練損傷予防指導。</li><li>環境衛生と食品医薬品安全監督。</li><li>突発公衆衛生事件の緊急応答。</li></ol><h2 id="第七節-法律責任" tabindex="-1">第七節 法律責任 <a class="header-anchor" href="#第七節-法律責任" aria-label="Permalink to &quot;第七節 法律責任&quot;">​</a></h2><p>本法の規定に違反する行為は、情状の軽重に応じて以下の責任を負う：</p><ul><li>医療機関が救急患者を拒否した場合、是正を命じ罰金を科し、深刻な結果を引き起こした場合は執業許可を取り消す。</li><li>医療人員が重大な過失により患者に損害を与えた場合、賠償責任を負い、情状が深刻な場合は執業資格を取り消す。</li><li>医療機関が違反して料金を徴収し、過剰医療を行った場合、料金の返還を命じ罰金を科す。</li><li>患者の医療プライバシーを漏洩した場合、精神的損害賠償を負い、情状が深刻な場合は刑事責任を追及する。</li><li>偽薬、劣悪薬を生産販売した場合、違法所得を没収し罰金を科し、犯罪を構成する場合は刑事責任を追及する。</li></ul><h2 id="結語" tabindex="-1">結語 <a class="header-anchor" href="#結語" aria-label="Permalink to &quot;結語&quot;">​</a></h2><p>《医療保障法》はアンカー共生文明の「人人有路」理念の健康分野における体現である。それは普遍的にカバーされた医療保障体系を構築し、修練損傷専門科を設立し、救急救治権を保障することにより、各生命が病気や怪我の際にタイムリーな治療を受けられることを確保し、万族共進のために健康の基礎を固める。</p><h2 id="関連文書" tabindex="-1">関連文書 <a class="header-anchor" href="#関連文書" aria-label="Permalink to &quot;関連文書&quot;">​</a></h2><ul><li>40-共生宪法总纲 (共生憲法総綱)</li><li>38-共生医疗体系 (共生医療体系)</li><li>45-住房保障法 (住宅保障法)</li><li>08-人人有路保障体系 (人人有路保障体系)</li></ul>',29)])])}const p=a(i,[["render",e]]);export{u as __pageData,p as default};
